import{_ as a,o as e,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"工作流与多 Agent 总览","description":"","frontmatter":{"title":"工作流与多 Agent 总览"},"headers":[],"relativePath":"ts-ai/workflow/index.md","filePath":"ts-ai/workflow/index.md","lastUpdated":1786083160000}'),d={name:"ts-ai/workflow/index.md"};function s(o,t,i,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="工作流与多-agent-总览" tabindex="-1">工作流与多 Agent 总览 <a class="header-anchor" href="#工作流与多-agent-总览" aria-label="Permalink to &quot;工作流与多 Agent 总览&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>用 <strong>LangGraph.js 状态图</strong>表达「步骤、分支、持久恢复与人工介入」；用 <strong>多 Agent</strong> 表达「职责隔离后的协作」。两者都不要默认比单 Agent / 固定 Chain 更好——先证明单图或单 Agent 不够。</p><p>前置：<a href="/ts-ai/agent/">Agent 开发</a>（至少读过 <a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a>）；服务端落库与队列见 <a href="/ts-ai/backend/">服务端工程</a>。</p><p><strong>怎么读：</strong></p><ol><li>先读 <a href="/ts-ai/workflow/workflow-foundations/workflow-principles-boundaries">工作流原理与边界</a></li><li>立刻跑 <a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a></li><li>再学 LangGraph 核心 → 持久执行</li><li><strong>多 Agent 为进阶</strong>：单图 + Checkpoint/Interrupt 不通不要先啃</li><li>质量组贯穿验证；最后用 <a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">组装配方与自检</a> 收束</li></ol><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>你在学什么</th><th>优先级</th></tr></thead><tbody><tr><td><a href="/ts-ai/workflow/workflow-foundations/">工作流基础</a></td><td>何时用图、与 Agent/Chain 边界、最小可跑通图</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/workflow/langgraph-core/">LangGraph.js 核心</a></td><td>建模、<code>StateGraph</code>、Reducer、路由、并行循环、Subgraph</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/workflow/durable-execution/">持久执行</a></td><td>Checkpoint/Store、Interrupt/Command、恢复、幂等、状态迁移</td><td><strong>必学</strong></td></tr><tr><td><a href="/ts-ai/workflow/multi-agent/">多 Agent</a></td><td>模式、Supervisor、共享状态、Network、Deep Agents、A2A</td><td><strong>进阶</strong></td></tr><tr><td><a href="/ts-ai/workflow/workflow-quality/">工作流质量</a></td><td>图测试、状态迁移测试、Trace、队列接缝、发布兼容</td><td><strong>必学</strong>（可与多 Agent 并行，但应先覆盖单图）</td></tr><tr><td><a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">组装配方与能力自检</a></td><td>场景配方与跨组勾选</td><td><strong>必学</strong>（模块末）</td></tr></tbody></table><h2 id="跨章所有权" tabindex="-1">跨章所有权 <a class="header-anchor" href="#跨章所有权" aria-label="Permalink to &quot;跨章所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>Checkpoint / Store</td><td>图执行快照、线程恢复、与 Interrupt 配合</td><td><a href="/ts-ai/knowledge/memory/checkpoint-store">记忆·Checkpoint 与 Store</a> 讲记忆语义</td></tr><tr><td>队列 / 长任务</td><td>图任务与图状态边界、租约/取消与图恢复</td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ</a> 队列基础设施；<code>agent-run</code> ≠ 图 Job</td></tr><tr><td>Interrupt / HITL</td><td>图内暂停、<code>Command</code> 恢复</td><td>前端确认 UI → <a href="/ts-ai/integration/">integration</a></td></tr><tr><td>多 Agent vs 单 Agent</td><td>何时拆、拓扑、终止与成本</td><td><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent Runtime 边界</a></td></tr><tr><td>Trace / 观测</td><td>图路径、节点延迟与失败定位</td><td>全站 SLO / OTel → <a href="/ts-ai/quality/">质量与生产</a></td></tr><tr><td>A2A vs MCP</td><td>远程 Agent 任务/产物交换</td><td>MCP 工具协议 → <a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr></tbody></table><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原理与边界 → 最小可运行 StateGraph</span></span>
<span class="line"><span>  → LangGraph.js 核心 → 持久执行</span></span>
<span class="line"><span>  → 工作流质量（至少 Graph 测试 + 队列边界）</span></span>
<span class="line"><span>  →（可选）多 Agent</span></span>
<span class="line"><span>  → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="和「再套一层-createagent」的区别" tabindex="-1">和「再套一层 createAgent」的区别 <a class="header-anchor" href="#和「再套一层-createagent」的区别" aria-label="Permalink to &quot;和「再套一层 createAgent」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>固定 Chain / 单 Agent</th><th>本模块工作流（图）</th><th>多 Agent</th></tr></thead><tbody><tr><td>控制流</td><td>隐式循环或固定 pipe</td><td>显式节点 / 边 / 终态</td><td>多角色协作拓扑</td></tr><tr><td>持久恢复</td><td>通常靠会话消息</td><td>Checkpoint + Interrupt</td><td>同上 + 共享/私有状态</td></tr><tr><td>失败样子</td><td>工具死循环、上下文爆</td><td>路由错、重放副作用、无法恢复</td><td>级联、权责不清、永不终止</td></tr></tbody></table>`,14)])])}const b=a(d,[["render",s]]);export{g as __pageData,b as default};
